body.append('email', 'kunde.eloisa@example.com');
body.append('country_code', 'consequatur');
body.append('phone', 'mqeopfuudtdsufvyv');
body.append('delete_avatar', '');
body.append('postal_code', 'ddqamniihfqcoynla');
body.append('main_address', 'consequatur');
body.append('avatar', document.querySelector('input[name="avatar"]').files[0]);

fetch(url, {
    method: "POST",
    headers,
    body,
}).then(response =&gt; response.json());</code></pre></div>

